'use strict';
const {parts,joints,shape,assembly,boxes,counts}=OBTPKit;
let selected='post01',view='assembly',joint='j01',explode=0,bays=1,layer='all';const $=id=>document.getElementById(id);
function draw(bs){const projected=[],polygons=[],project=([x,y,z])=>[(x-y)*.866,(x+y)*.5-z];for(const b of bs){const[x,y,z]=b.p,[a,c,h]=b.d;const vs=[[x,y,z],[x+a,y,z],[x+a,y+c,z],[x,y+c,z],[x,y,z+h],[x+a,y,z+h],[x+a,y+c,z+h],[x,y+c,z+h]],v=vs.map(project);projected.push(...v);for(const[ids,shade]of [[[1,2,6,5],0],[[2,3,7,6],1],[[4,5,6,7],2]]){const depth=ids.reduce((s,i)=>s+vs[i][0]+vs[i][1]+vs[i][2]*.9,0)/ids.length;polygons.push({points:ids.map(i=>v[i]),depth,part:b.part,fill:b.blue?['#4550e6','#303bb9','#8a92fa'][shade]:['#d7d8de','#bfc1ca','#fafafa'][shade]});}}
const xs=projected.map(p=>p[0]),ys=projected.map(p=>p[1]),minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys),s=Math.min(640/Math.max(.1,maxX-minX),320/Math.max(.1,maxY-minY));$('diagram').innerHTML='<title>'+ (view==='assembly'?bays+' bay geometric assembly':selected+' component study')+'</title>'+polygons.sort((a,b)=>a.depth-b.depth).map(p=>`<polygon points="${p.points.map(([x,y])=>[400+(x-(minX+maxX)/2)*s,225+(y-(minY+maxY)/2)*s].join(',')).join(' ')}" fill="${p.fill}" stroke="#434650" stroke-width=".8" stroke-linejoin="round"/>`).join('');}
function jointItems(j){const e=explode/100;switch(j.id){case'j01':return[{part:'post01',p:[0,0,0]},{part:'beam01',p:[0,0,2.4+e]}];case'j02':return[{part:'beam01',p:[.16,0,0],rot:90},{part:'beam02',p:[.16+e,0,0]}];case'j03':return[{part:'post01',p:[0,0,0]},{part:'wall01',p:[0,-.18-e,0]}];case'j04':return[{part:'floor01',p:[0,0,0]},{part:'wall03',p:[0,-.26-e,.24]}];case'j05':return[{part:'beam02',p:[0,0,0]},{part:'roof01',p:[0,0,.32+e]}];default:return[{part:'wall01',p:[0,0,0]},{part:'wall02',p:[1.2+e,0,0]}];}}
function render(){const p=parts.find(p=>p.id===selected),j=joints.find(j=>j.id===joint);$('types').innerHTML=[...new Set(parts.map(p=>p.type))].map(t=>`<button data-type="${t}" aria-pressed="${p.type===t}">${t}<span>${parts.filter(p=>p.type===t).length}</span></button>`).join('');$('objects').innerHTML=parts.filter(a=>a.type===p.type).map(a=>`<button data-part="${a.id}" aria-pressed="${selected===a.id}">${a.id}</button>`).join('');$('family').textContent=view==='assembly'?'Frame + panels / geometric fit study':p.type+' / provisional';$('title').textContent=view==='object'?selected:view==='connection'?j.name:bays===1?'One bay / 3.6 × 2.4 m':'Two bays / 7.2 × 2.4 m';$('connections').hidden=view!=='connection';$('connections').innerHTML=joints.map(a=>`<button data-joint="${a.id}" aria-pressed="${joint===a.id}">${a.name}</button>`).join('');document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.view===view));document.querySelectorAll('[data-bays]').forEach(b=>b.setAttribute('aria-pressed',+b.dataset.bays===bays));$('assembly-controls').hidden=view!=='assembly';$('explode-control').hidden=view==='object';$('explode').value=explode;$('explode-value').textContent=explode+'%';$('drawing-label').textContent=view==='assembly'?'AXO / '+layer.toUpperCase()+' · HIGHLIGHT '+selected.toUpperCase():view==='object'?'LOCAL COMPONENT ENVELOPE':'CONCEPTUAL INTERFACE / '+j.id.toUpperCase();$('schedule').hidden=view!=='assembly';
let bs;if(view==='object'){bs=shape(selected).map(b=>({...b,blue:true}));$('details').innerHTML=`<div><span class="eyebrow">Role</span><p>${p.role}</p></div><div><span class="eyebrow">Physical envelope</span><p><strong>${p.d.map(v=>Math.round(v*1000)).join(' × ')} mm</strong></p><p>${p.axis}</p></div><div><span class="eyebrow">Attachment faces</span><p>${p.faces}</p><p>Geometry proposed / capacity unverified</p></div>`;}
else if(view==='connection'){bs=boxes(jointItems(j),{highlight:j.ids[1]});$('details').innerHTML=`<div><span class="eyebrow">Parts</span><p>${j.ids.join(' + ')}</p></div><div><span class="eyebrow">Alignment rule</span><p>${j.rule}</p></div><div><span class="eyebrow">Unresolved</span><p>${j.open}</p></div>`;}
else{const items=assembly(bays);bs=boxes(items,{explode,layer,highlight:selected});const quantities=counts(items);$('details').innerHTML=`<div><span class="eyebrow">Setting-out</span><p><strong>${(3.6*bays).toFixed(1)} × 2.4 m</strong> between axes</p><p>600 mm grid / 1,200 mm panel pitch</p></div><div><span class="eyebrow">Library usage</span><p><strong>${items.length} component instances</strong></p><p>${parts.length} unique definitions / complete study assembly</p></div><div><span class="eyebrow">Shared frame</span><p>${bays===2?'Central posts and transverse beam counted once.':'Four posts and four beams.'}</p><p>Geometric arrangement only</p></div>`;$('schedule').innerHTML='<h3>Assembly quantities / all stages</h3><table><thead><tr><th>Object</th><th>Count</th><th>Role</th></tr></thead><tbody>'+quantities.map(r=>`<tr><td>${r.id}</td><td>${r.count}</td><td>${parts.find(p=>p.id===r.id).role}</td></tr>`).join('')+'</tbody></table><p class="note">Counts come from the same instances shown in the assembly. Excludes foundations, bracing, rails, fasteners, closures and finishes.</p>';}
draw(bs);}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.type)selected=parts.find(p=>p.type===b.dataset.type).id;if(b.dataset.part)selected=b.dataset.part;if(b.dataset.type||b.dataset.part){if(view==='connection')joint=joints.find(j=>j.ids.includes(selected))?.id||joint;}
if(b.dataset.view)view=b.dataset.view;if(b.dataset.joint)joint=b.dataset.joint;if(b.dataset.bays)bays=+b.dataset.bays;render();});$('explode').addEventListener('input',e=>{explode=+e.target.value;render();});$('layer').addEventListener('change',e=>{layer=e.target.value;render();});render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'inspect_system',description:'Select a component, assembly count and view in the System study.',inputSchema:{type:'object',properties:{id:{type:'string',enum:parts.map(p=>p.id)},view:{type:'string',enum:['object','connection','assembly']},bays:{type:'integer',enum:[1,2]}},required:['id','view'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!parts.some(p=>p.id===input.id)||!['object','connection','assembly'].includes(input.view)||(input.bays!==undefined&&![1,2].includes(input.bays)))throw Error('Unknown part, view or bay count');selected=input.id;view=input.view;bays=input.bays||bays;joint=joints.find(j=>j.ids.includes(selected))?.id||joint;render();return{selected,view,bays,provisional:true};}})).catch(()=>{});}catch{}}
